// Point deductions ordered from LEAST deduction to MOST deduction:
// Hemisphere (-75) < Borders/Landmark (-150) < Continent (-250) < Capital/Host Country (-350)
const CLUE_DEDUCTIONS = {
    hemisphere: 75,
    borders: 150,
    continent: 250,
    capital: 350
};

class WorldleGame {
    constructor() {
        this.targetCountries = WORLDLE_TARGET_COUNTRIES;
        this.allCountries = WORLDLE_ALL_COUNTRIES;
        this.cities = WORLDLE_CITIES;
        this.countryByCode = {};
        this.targetCountries.forEach(c => {
            this.countryByCode[c.code] = c;
        });

        this.mode = "countries"; // "countries" or "cities"
        this.mapStyle = "atlas"; // "atlas" | "satellite" | "outline"
        this.cityZoom = false;   // Zoomed regional metro view in cities mode
        this.countryIndex = 0;
        this.cityIndex = 0;
        this.target = null;
        this.guesses = [];
        this.maxGuesses = 6;
        this.isPlaying = false;
        this.gameOver = false;
        this.wins = 0;
        this.streak = 0;
        this.totalScore = 0;
        this.roundPotential = 1000;
        this.useMiles = false;
        this.rotateMode = false;
        this.rotationDeg = 0;
        this.revealedIntel = new Set();
        this.activeSuggestionIdx = -1;

        this.mapEl = document.getElementById("worldleMapContainer");
        this.inputEl = document.getElementById("worldleInput");
        this.suggestionsEl = document.getElementById("worldleSuggestions");
        this.guessesEl = document.getElementById("worldleGuesses");
        this.guessCountEl = document.getElementById("worldleGuessCount");
        this.winsEl = document.getElementById("worldleWins");
        this.streakEl = document.getElementById("worldleStreak");
        this.scoreEl = document.getElementById("worldleScore");
        this.potentialEl = document.getElementById("worldleRoundPotential");
        this.intelOutputEl = document.getElementById("worldleIntelOutput");
        this.unitBtn = document.getElementById("worldleUnitBtn");
        this.rotateBtn = document.getElementById("worldleRotateBtn");
        this.modeCountriesBtn = document.getElementById("worldleModeCountries");
        this.modeCitiesBtn = document.getElementById("worldleModeCities");
        this.bordersLabelEl = document.getElementById("intelBordersLabel");
        this.capitalLabelEl = document.getElementById("intelCapitalLabel");

        const startBtn = document.getElementById("startWorldle");
        if (startBtn) startBtn.addEventListener("click", () => this.startGame());

        const submitBtn = document.getElementById("submitWorldle");
        if (submitBtn) submitBtn.addEventListener("click", () => this.submitGuess());

        const hintBtn = document.getElementById("hintWorldle");
        if (hintBtn) hintBtn.addEventListener("click", () => this.revealNextIntel());

        const newBtn = document.getElementById("newWorldle");
        if (newBtn) newBtn.addEventListener("click", () => this.nextTarget());

        if (this.modeCountriesBtn) {
            this.modeCountriesBtn.addEventListener("click", () => this.switchMode("countries"));
        }
        if (this.modeCitiesBtn) {
            this.modeCitiesBtn.addEventListener("click", () => this.switchMode("cities"));
        }

        if (this.unitBtn) {
            this.unitBtn.addEventListener("click", () => {
                this.useMiles = !this.useMiles;
                this.unitBtn.textContent = this.useMiles ? "mi" : "km";
                this.render();
            });
        }

        if (this.rotateBtn) {
            this.rotateBtn.addEventListener("click", () => {
                this.rotateMode = !this.rotateMode;
                this.rotationDeg = this.rotateMode ? [90, 180, 270][Math.floor(Math.random() * 3)] : 0;
                this.rotateBtn.classList.toggle("active", this.rotateMode);
                this.rotateBtn.textContent = this.rotateMode ? `🔄 Rotated (${this.rotationDeg}°)` : "🧭 North-Up";
                this.renderMap();
            });
        }

        document.querySelectorAll(".worldle-intel-chip").forEach(chip => {
            chip.addEventListener("click", () => {
                const type = chip.getAttribute("data-intel");
                this.showIntel(type);
            });
        });

        if (this.inputEl) {
            this.inputEl.addEventListener("input", () => this.updateSuggestions());
            this.inputEl.addEventListener("keydown", (e) => this.handleInputKeydown(e));
        }

        this.loadStats();
        this.showStartScreen();

        if (window.arcadeApp) {
            window.arcadeApp.registerGame("worldle", this);
        }
    }

    loadStats() {
        if (window.ScoreStorage) {
            window.ScoreStorage.get("worldleWins", (w) => {
                this.wins = w || 0;
                if (this.winsEl) this.winsEl.textContent = this.wins;
            });
            window.ScoreStorage.get("worldleStreak", (s) => {
                this.streak = s || 0;
                if (this.streakEl) this.streakEl.textContent = this.streak;
            });
            window.ScoreStorage.get("worldleScore", (sc) => {
                this.totalScore = sc || 0;
                if (this.scoreEl) this.scoreEl.textContent = this.totalScore.toLocaleString();
            });
        }
    }

    saveStats() {
        if (this.winsEl) this.winsEl.textContent = this.wins;
        if (this.streakEl) this.streakEl.textContent = this.streak;
        if (this.scoreEl) this.scoreEl.textContent = this.totalScore.toLocaleString();
        if (window.ScoreStorage) {
            window.ScoreStorage.set("worldleWins", this.wins);
            window.ScoreStorage.set("worldleStreak", this.streak);
            window.ScoreStorage.set("worldleScore", this.totalScore);
        }
    }

    pause() {}

    switchMode(newMode) {
        if (this.mode === newMode && this.isPlaying) return;
        this.mode = newMode;
        this.cityZoom = false;
        if (this.modeCountriesBtn) this.modeCountriesBtn.classList.toggle("active", newMode === "countries");
        if (this.modeCitiesBtn) this.modeCitiesBtn.classList.toggle("active", newMode === "cities");

        if (this.bordersLabelEl) {
            this.bordersLabelEl.textContent = newMode === "cities" ? "🚧 River / Landmark" : "🚧 Borders / Coast";
        }
        if (this.capitalLabelEl) {
            this.capitalLabelEl.textContent = newMode === "cities" ? "🏛️ Host Country" : "🏛️ Capital / City";
        }
        if (this.inputEl) {
            this.inputEl.placeholder = newMode === "cities"
                ? "Search 50+ world cities (e.g. London, Tokyo, Paris, New York)..."
                : "Search 240+ countries or territories...";
        }

        if (this.isPlaying) {
            this.loadCurrentTarget();
        } else {
            this.startGame();
        }
    }

    cycleMapStyle() {
        const order = ["atlas", "satellite", "outline"];
        const idx = (order.indexOf(this.mapStyle) + 1) % order.length;
        this.mapStyle = order[idx];
        this.renderMap();
    }

    toggleCityZoom() {
        this.cityZoom = !this.cityZoom;
        this.renderMap();
    }

    showStartScreen() {
        if (this.mapEl) {
            this.mapEl.innerHTML = '<div style="text-align: center; color: #94a3b8; font-size: 0.9rem; padding: 1rem;">Click <b>Start Game</b> (or select <b>🌍 Countries</b> / <b>🏙️ World Cities</b> above)</div>';
        }
    }

    startGame() {
        this.isPlaying = true;
        this.loadCurrentTarget();
    }

    nextTarget() {
        if (!this.isPlaying) {
            this.startGame();
            return;
        }
        if (this.mode === "cities") {
            this.cityIndex = (this.cityIndex + 1) % this.cities.length;
        } else {
            this.countryIndex = (this.countryIndex + 1) % this.targetCountries.length;
        }
        this.loadCurrentTarget();
    }

    loadCurrentTarget() {
        this.target = this.mode === "cities"
            ? this.cities[this.cityIndex]
            : this.targetCountries[this.countryIndex];
        this.guesses = [];
        this.gameOver = false;
        this.revealedIntel.clear();
        this.activeSuggestionIdx = -1;
        this.rotationDeg = this.rotateMode ? [90, 180, 270][Math.floor(Math.random() * 3)] : 0;

        document.querySelectorAll(".worldle-intel-chip").forEach(c => c.classList.remove("revealed"));
        this.recalculateRoundPotential();

        if (this.intelOutputEl) {
            this.intelOutputEl.textContent = this.mode === "cities"
                ? "📍 Red radar beacon marks the city's exact location! Solve with 0 clues for 1,000 pts."
                : "Solve with 0 clues for the full 1,000-pt No-Clue Bonus!";
        }

        if (this.inputEl) {
            this.inputEl.value = "";
            this.inputEl.focus();
        }
        if (this.suggestionsEl) this.suggestionsEl.classList.add("hidden");
        this.render();
        if (window.sounds) window.sounds.launch();
    }

    recalculateRoundPotential() {
        let score = 1000;
        this.revealedIntel.forEach(type => {
            score -= (CLUE_DEDUCTIONS[type] || 0);
        });
        const wrongGuesses = this.guesses.filter(g => g.distKm > 0).length;
        score -= wrongGuesses * 40;
        this.roundPotential = Math.max(100, score);
        if (this.potentialEl) {
            this.potentialEl.textContent = this.roundPotential;
        }
        return this.roundPotential;
    }

    getIntelText(type) {
        if (!this.target) return "";
        if (type === "hemisphere") {
            const ns = this.target.lat >= 0 ? "Northern" : "Southern";
            const ew = this.target.lon >= 0 ? "Eastern" : "Western";
            const tropic = Math.abs(this.target.lat) <= 23.5 ? "Tropical Zone" : (Math.abs(this.target.lat) >= 60 ? "Subpolar Zone" : "Temperate Zone");
            return `🌐 [-75 pts] ${ns} & ${ew} Hemisphere • ${tropic} (~${Math.abs(Math.round(this.target.lat))}°${this.target.lat >= 0 ? "N" : "S"})`;
        }
        if (type === "borders") {
            return `🚧 [-150 pts] ${this.target.borders}`;
        }
        if (type === "continent") {
            return `🗺️ [-250 pts] Continent: ${this.target.continent} (${this.target.subregion})`;
        }
        if (type === "capital") {
            if (this.mode === "cities") {
                return `🏛️ [-350 pts] ${this.target.capital} • City starts with '${this.target.name[0]}'`;
            }
            return `🏛️ [-350 pts] Capital City: ${this.target.capital} (${this.target.name.length} letters in country name)`;
        }
        return "";
    }

    showIntel(type) {
        if (!this.isPlaying || !this.target) {
            this.startGame();
        }
        if (this.gameOver) return;

        const isNew = !this.revealedIntel.has(type);
        this.revealedIntel.add(type);
        const chip = document.querySelector(`.worldle-intel-chip[data-intel="${type}"]`);
        if (chip) chip.classList.add("revealed");

        this.recalculateRoundPotential();
        const text = this.getIntelText(type);
        if (this.intelOutputEl) {
            this.intelOutputEl.textContent = text;
        }
        if (isNew && window.showToast) {
            const cost = CLUE_DEDUCTIONS[type] || 0;
            window.showToast(`Clue unlocked (-${cost} pts) • Round Potential: ${this.roundPotential} pts`, "📡");
        }
        if (window.sounds) window.sounds.score();
    }

    revealNextIntel() {
        if (!this.isPlaying || this.gameOver || !this.target) {
            this.startGame();
            return;
        }
        const orderLeastToMost = ["hemisphere", "borders", "continent", "capital"];
        const nextType = orderLeastToMost.find(t => !this.revealedIntel.has(t)) || "capital";
        this.showIntel(nextType);
    }

    getSearchPool() {
        return this.mode === "cities" ? this.cities : this.allCountries;
    }

    handleInputKeydown(e) {
        const items = this.suggestionsEl ? Array.from(this.suggestionsEl.querySelectorAll(".worldle-suggestion-item")) : [];
        if (e.key === "ArrowDown" && items.length > 0) {
            e.preventDefault();
            this.activeSuggestionIdx = (this.activeSuggestionIdx + 1) % items.length;
            this.highlightSuggestion(items);
        } else if (e.key === "ArrowUp" && items.length > 0) {
            e.preventDefault();
            this.activeSuggestionIdx = (this.activeSuggestionIdx - 1 + items.length) % items.length;
            this.highlightSuggestion(items);
        } else if (e.key === "Enter") {
            e.preventDefault();
            if (this.activeSuggestionIdx >= 0 && items[this.activeSuggestionIdx]) {
                this.inputEl.value = items[this.activeSuggestionIdx].getAttribute("data-country");
                this.suggestionsEl.classList.add("hidden");
                this.activeSuggestionIdx = -1;
            }
            this.submitGuess();
        } else if (e.key === "Escape" && this.suggestionsEl) {
            this.suggestionsEl.classList.add("hidden");
        }
    }

    highlightSuggestion(items) {
        items.forEach((el, idx) => {
            el.classList.toggle("active-suggestion", idx === this.activeSuggestionIdx);
        });
    }

    updateSuggestions() {
        if (!this.inputEl || !this.suggestionsEl) return;
        const val = this.inputEl.value.toUpperCase().trim();
        this.activeSuggestionIdx = -1;
        if (!val) {
            this.suggestionsEl.classList.add("hidden");
            return;
        }

        const pool = this.getSearchPool();
        const starts = pool.filter(c => c.name.startsWith(val));
        const includes = pool.filter(c => !c.name.startsWith(val) && c.name.includes(val));
        const matches = [...starts, ...includes].slice(0, 7);

        if (matches.length === 0) {
            this.suggestionsEl.classList.add("hidden");
            return;
        }

        this.suggestionsEl.innerHTML = matches.map(c => `
            <div class="worldle-suggestion-item" data-country="${c.name}">
                <span>${this.mode === "cities" ? "🏙️" : (c.flag || "🌍")} ${c.name}</span>
                <span style="font-size: 0.72rem; color: #94a3b8; font-weight: 600;">${c.continent || ""}</span>
            </div>
        `).join("");
        this.suggestionsEl.classList.remove("hidden");

        this.suggestionsEl.querySelectorAll(".worldle-suggestion-item").forEach(el => {
            el.addEventListener("click", () => {
                this.inputEl.value = el.getAttribute("data-country");
                this.suggestionsEl.classList.add("hidden");
                this.submitGuess();
            });
        });
    }

    calculateGeoMetrics(from, to) {
        if (from.name === to.name) {
            return {
                distKm: 0,
                bearingDeg: 0,
                compassCode: "TARGET",
                arrow: "🎯",
                proximity: 100,
                blocks: "🟩🟩🟩🟩🟩"
            };
        }

        const toRad = d => (d * Math.PI) / 180;
        const R = 6371;
        const dLat = toRad(to.lat - from.lat);
        const dLon = toRad(to.lon - from.lon);
        const lat1 = toRad(from.lat);
        const lat2 = toRad(to.lat);

        const a = Math.sin(dLat / 2) ** 2 + Math.cos(lat1) * Math.cos(lat2) * Math.sin(dLon / 2) ** 2;
        const distKm = Math.round(R * 2 * Math.atan2(Math.sqrt(a), Math.sqrt(1 - a)));

        const y = Math.sin(dLon) * Math.cos(lat2);
        const x = Math.cos(lat1) * Math.sin(lat2) - Math.sin(lat1) * Math.cos(lat2) * Math.cos(dLon);
        const brng = Math.round(((Math.atan2(y, x) * 180) / Math.PI + 360) % 360);

        const arrows = ["⬆️", "↗️", "➡️", "↘️", "⬇️", "↙️", "⬅️", "↖️"];
        const codes = ["N", "NE", "E", "SE", "S", "SW", "W", "NW"];
        const idx = Math.round(brng / 45) % 8;
        const arrow = arrows[idx];
        const compassCode = codes[idx];

        const proximity = Math.max(0, Math.min(99, Math.round((1 - distKm / 20000) * 100)));
        const greenCount = Math.floor(proximity / 20);
        const hasHalf = (proximity % 20) >= 10 && greenCount < 5;
        const emptyCount = 5 - greenCount - (hasHalf ? 1 : 0);
        const blocks = "🟩".repeat(greenCount) + (hasHalf ? "🟨" : "") + "⬛".repeat(Math.max(0, emptyCount));

        return { distKm, bearingDeg: brng, compassCode, arrow, proximity, blocks };
    }

    formatDistance(distKm) {
        if (this.useMiles) {
            return `${Math.round(distKm * 0.621371).toLocaleString()} mi`;
        }
        return `${distKm.toLocaleString()} km`;
    }

    submitGuess() {
        if (!this.isPlaying || this.gameOver) {
            this.startGame();
            return;
        }
        if (!this.inputEl) return;

        const pool = this.getSearchPool();
        const typed = this.inputEl.value.toUpperCase().trim();
        let entry = pool.find(c => c.name === typed);
        if (!entry) {
            entry = pool.find(c => c.name.startsWith(typed) && typed.length >= 3);
        }
        if (!entry) {
            const label = this.mode === "cities" ? "city" : "country";
            if (window.showToast) window.showToast(`Select a valid ${label} from the autocomplete list!`, "🌍");
            return;
        }

        if (this.guesses.some(g => g.name === entry.name)) {
            if (window.showToast) window.showToast(`You already guessed ${entry.name}!`, "⚠️");
            return;
        }

        this.inputEl.value = "";
        if (this.suggestionsEl) this.suggestionsEl.classList.add("hidden");

        const metrics = this.calculateGeoMetrics(entry, this.target);
        const icon = this.mode === "cities" ? "🏙️" : (entry.flag || "🌍");
        this.guesses.push({ name: entry.name, flag: icon, ...metrics });
        this.recalculateRoundPotential();
        this.render();

        if (entry.name === this.target.name) {
            this.gameOver = true;
            this.wins++;
            this.streak++;
            const earnedPts = this.roundPotential;
            this.totalScore += earnedPts;
            this.saveStats();

            const cluesUsed = this.revealedIntel.size;
            const bonusTag = cluesUsed === 0 ? "🏆 NO-CLUE PERFECT BONUS!" : `${cluesUsed} clue(s) used`;
            const subDesc = this.mode === "cities"
                ? `${this.target.flag} ${this.target.name}, ${this.target.countryName} • +${earnedPts} pts (${bonusTag})`
                : `Capital: ${this.target.capital} • +${earnedPts} pts (${bonusTag})`;

            if (window.celebrateWin) {
                setTimeout(() => {
                    window.celebrateWin({
                        title: `+${earnedPts} PTS • ${this.target.name}!`,
                        subtitle: subDesc,
                        trophy: cluesUsed === 0 ? "🏆" : "🌍",
                        stats: [
                            { label: this.mode === "cities" ? "City" : "Country", val: `${this.target.flag} ${this.target.name}` },
                            { label: "Points Earned", val: `+${earnedPts}` },
                            { label: "Clues Used", val: cluesUsed === 0 ? "0 (Max Bonus!)" : cluesUsed },
                            { label: "Total Score", val: this.totalScore.toLocaleString() }
                        ],
                        onRestart: () => this.nextTarget()
                    });
                }, 350);
            }
        } else if (this.guesses.length >= this.maxGuesses) {
            this.gameOver = true;
            this.streak = 0;
            this.saveStats();
            if (window.showGameOverModal) {
                setTimeout(() => {
                    window.showGameOverModal({
                        title: `${this.target.flag} ${this.target.name}`,
                        subtitle: this.mode === "cities"
                            ? `${this.target.name} (${this.target.countryName}) • ${this.target.borders}`
                            : `Capital: ${this.target.capital} • ${this.target.borders}`,
                        icon: "🌍",
                        stats: [
                            { label: "Answer", val: `${this.target.flag} ${this.target.name}` },
                            { label: "Total Score", val: this.totalScore.toLocaleString() }
                        ],
                        onRestart: () => this.nextTarget()
                    });
                }, 350);
            }
        } else {
            if (window.sounds) window.sounds.score();
        }
    }

    renderMap() {
        if (!this.mapEl || !this.target) return;

        // Resolve map source (either target country directly or host country for a city)
        const mapSource = this.mode === "cities"
            ? (this.countryByCode[this.target.countryCode] || this.target)
            : this.target;

        const svgPath = mapSource.svg || "";
        const neighborsPath = mapSource.neighborsSvg || "";
        const lakesPath = mapSource.lakesSvg || "";
        const riversPath = mapSource.riversSvg || "";

        const scaleLabel = this.useMiles
            ? `~${Math.round(this.target.widthKm * 0.621371).toLocaleString()} mi`
            : `~${this.target.widthKm.toLocaleString()} km`;
        const compassLabel = this.rotateMode ? `ROT ${this.rotationDeg}°` : "N ▲";

        const styleBadgeText = this.mapStyle === "atlas"
            ? "🗺️ Physical Atlas"
            : (this.mapStyle === "satellite" ? "🛰️ Satellite" : "🟢 Outline");

        // Compute viewBox (support 2.1x regional zoom around city pin in Cities mode!)
        let viewBox = "0 0 240 240";
        if (this.mode === "cities" && this.cityZoom) {
            const span = 112;
            const vx = Math.max(0, Math.min(240 - span, this.target.pinX - span / 2));
            const vy = Math.max(0, Math.min(240 - span, this.target.pinY - span / 2));
            viewBox = `${vx.toFixed(1)} ${vy.toFixed(1)} ${span} ${span}`;
        }

        const showContext = this.mapStyle !== "outline";
        const isSat = this.mapStyle === "satellite";

        // Graticule grid lines (every 48px)
        const graticuleMarkup = `
            <g class="worldle-graticule" stroke="rgba(125, 211, 252, 0.14)" stroke-width="0.6" stroke-dasharray="2,3">
                <line x1="48" y1="0" x2="48" y2="240" />
                <line x1="96" y1="0" x2="96" y2="240" />
                <line x1="144" y1="0" x2="144" y2="240" />
                <line x1="192" y1="0" x2="192" y2="240" />
                <line x1="0" y1="48" x2="240" y2="48" />
                <line x1="0" y1="96" x2="240" y2="96" />
                <line x1="0" y1="144" x2="240" y2="144" />
                <line x1="0" y1="192" x2="240" y2="192" />
            </g>
        `;

        // Shallow coastal shelf water glow + Neighboring countries
        const contextMarkup = showContext ? `
            <!-- Turquoise Continental Shelf Shallow-Water Glow -->
            ${neighborsPath ? `<path d="${neighborsPath}" fill="none" stroke="${isSat ? 'rgba(6, 182, 212, 0.22)' : 'rgba(56, 189, 248, 0.26)'}" stroke-width="11" stroke-linejoin="round" />` : ""}
            <path d="${svgPath}" fill="none" stroke="${isSat ? 'rgba(34, 211, 238, 0.38)' : 'rgba(56, 189, 248, 0.48)'}" stroke-width="12" stroke-linejoin="round" />
            <path d="${svgPath}" fill="none" stroke="rgba(125, 211, 252, 0.55)" stroke-width="5" stroke-linejoin="round" />

            <!-- Surrounding Neighboring Countries Landmass -->
            ${neighborsPath ? `
                <path d="${neighborsPath}" fill="url(#worldleNeighborGrad)" stroke="${isSat ? '#334155' : '#64748b'}" stroke-width="1.1" stroke-linejoin="round" fill-rule="evenodd" />
                <path d="${neighborsPath}" fill="none" stroke="rgba(15, 23, 42, 0.65)" stroke-width="0.6" stroke-dasharray="3,2" stroke-linejoin="round" />
            ` : ""}
        ` : "";

        // Rivers & Lakes overlay
        const hydroMarkup = showContext ? `
            ${riversPath ? `<path d="${riversPath}" fill="none" stroke="${isSat ? '#22d3ee' : '#38bdf8'}" stroke-width="1.15" stroke-linecap="round" stroke-linejoin="round" opacity="0.82" />` : ""}
            ${lakesPath ? `<path d="${lakesPath}" fill="url(#worldleOceanGrad)" stroke="#7dd3fc" stroke-width="0.7" stroke-linejoin="round" fill-rule="evenodd" />` : ""}
        ` : "";

        // City Radar Pin + Crosshair in Cities Mode
        const cityPinMarkup = this.mode === "cities" ? `
            <g class="worldle-city-marker">
                <line x1="${this.target.pinX - 18}" y1="${this.target.pinY}" x2="${this.target.pinX + 18}" y2="${this.target.pinY}" stroke="rgba(254, 240, 138, 0.65)" stroke-width="0.9" stroke-dasharray="2,2" />
                <line x1="${this.target.pinX}" y1="${this.target.pinY - 18}" x2="${this.target.pinX}" y2="${this.target.pinY + 18}" stroke="rgba(254, 240, 138, 0.65)" stroke-width="0.9" stroke-dasharray="2,2" />
                <circle cx="${this.target.pinX}" cy="${this.target.pinY}" r="12" fill="none" stroke="rgba(239, 68, 68, 0.55)" stroke-width="1.4" />
                <circle cx="${this.target.pinX}" cy="${this.target.pinY}" r="9" fill="rgba(239, 68, 68, 0.38)" class="worldle-city-pulse" />
                <circle cx="${this.target.pinX}" cy="${this.target.pinY}" r="4.2" fill="#ef4444" stroke="#fef08a" stroke-width="1.8" />
            </g>
        ` : "";

        const zoomBtnMarkup = this.mode === "cities" ? `
            <button type="button" class="worldle-map-zoom-btn" id="worldleZoomToggleBtn" title="Toggle Regional Metro Zoom">
                ${this.cityZoom ? "🗺️ Country" : "🔍 Zoom City"}
            </button>
        ` : "";

        this.mapEl.innerHTML = `
            <button type="button" class="worldle-map-style-btn" id="worldleStyleToggleBtn" title="Switch Map Layer (Physical Atlas / Satellite / Classic Outline)">
                ${styleBadgeText}
            </button>
            ${zoomBtnMarkup}
            <span class="worldle-compass-badge">${compassLabel}</span>
            <svg class="worldle-svg" viewBox="${viewBox}" style="transform: rotate(${this.rotationDeg}deg);">
                <defs>
                    <!-- Deep Ocean Bathymetry Gradient -->
                    <radialGradient id="worldleOceanGrad" cx="50%" cy="50%" r="72%">
                        <stop offset="0%" stop-color="${isSat ? '#082f49' : '#0c4a6e'}" />
                        <stop offset="55%" stop-color="${isSat ? '#041e34' : '#082f49'}" />
                        <stop offset="100%" stop-color="${isSat ? '#020b16' : '#041628'}" />
                    </radialGradient>

                    <!-- Neighboring Countries Satellite Earth/Slate Gradient -->
                    <linearGradient id="worldleNeighborGrad" x1="0%" y1="0%" x2="100%" y2="100%">
                        <stop offset="0%" stop-color="${isSat ? '#16222f' : '#263346'}" />
                        <stop offset="50%" stop-color="${isSat ? '#111b26' : '#1e293b'}" />
                        <stop offset="100%" stop-color="${isSat ? '#0d151f' : '#172030'}" />
                    </linearGradient>

                    <!-- Target Country Physical Hypsometric / Satellite Terrain Gradient -->
                    <linearGradient id="worldleLandGrad" x1="0%" y1="0%" x2="100%" y2="100%">
                        <stop offset="0%" stop-color="${isSat ? '#059669' : '#4ade80'}" />
                        <stop offset="38%" stop-color="${isSat ? '#047857' : '#10b981'}" />
                        <stop offset="72%" stop-color="${isSat ? '#65a30d' : '#84cc16'}" />
                        <stop offset="100%" stop-color="${isSat ? '#ca8a04' : '#eab308'}" />
                    </linearGradient>

                    <!-- Interior Highland Topographic Contour Gradient -->
                    <radialGradient id="worldleHighlandGrad" cx="48%" cy="45%" r="55%">
                        <stop offset="0%" stop-color="rgba(254, 240, 138, 0.32)" />
                        <stop offset="55%" stop-color="rgba(16, 185, 129, 0.1)" />
                        <stop offset="100%" stop-color="rgba(6, 78, 59, 0.25)" />
                    </radialGradient>

                    <!-- 3D Drop Shadow & Coastal Relief Filter -->
                    <filter id="worldleLandShadow" x="-15%" y="-15%" width="130%" height="130%">
                        <feDropShadow dx="0" dy="2.5" stdDeviation="3.5" flood-color="#020617" flood-opacity="0.7" />
                    </filter>
                </defs>

                <!-- 1. Deep Ocean Bathymetry Background -->
                <rect x="-20" y="-20" width="280" height="280" fill="url(#worldleOceanGrad)" />
                ${graticuleMarkup}

                <!-- 2. Coastal Shelf & Surrounding Neighboring Countries -->
                ${contextMarkup}

                <!-- 3. Target Country Physical Terrain + Highland Relief + Crisp Border -->
                <g filter="url(#worldleLandShadow)">
                    <path d="${svgPath}" fill="url(#worldleLandGrad)" stroke="#020617" stroke-width="2.8" stroke-linejoin="round" fill-rule="evenodd" />
                    <path d="${svgPath}" fill="url(#worldleHighlandGrad)" stroke="${isSat ? '#38bdf8' : '#fef08a'}" stroke-width="1.4" stroke-linejoin="round" fill-rule="evenodd" />
                </g>

                <!-- 4. Natural Earth Rivers & Lakes -->
                ${hydroMarkup}

                <!-- 5. City Radar Pin (in World Cities mode) -->
                ${cityPinMarkup}
            </svg>
            <span class="worldle-scale-badge">${this.mode === "cities" ? "📍 GPS Radar • " : "📏 "}${scaleLabel}</span>
        `;

        const styleBtn = document.getElementById("worldleStyleToggleBtn");
        if (styleBtn) {
            styleBtn.addEventListener("click", (e) => {
                e.stopPropagation();
                this.cycleMapStyle();
            });
        }
        const zoomBtn = document.getElementById("worldleZoomToggleBtn");
        if (zoomBtn) {
            zoomBtn.addEventListener("click", (e) => {
                e.stopPropagation();
                this.toggleCityZoom();
            });
        }
    }

    render() {
        if (!this.target) return;

        if (this.guessCountEl) {
            this.guessCountEl.textContent = `${this.guesses.length} / ${this.maxGuesses}`;
        }

        this.renderMap();

        if (this.guessesEl) {
            this.guessesEl.innerHTML = this.guesses.map(g => `
                <div class="worldle-guess-row">
                    <span>${g.flag} ${g.name}</span>
                    <span class="worldle-blocks">${g.blocks}</span>
                    <span style="font-family: monospace; color: #e2e8f0; text-align: right;">${this.formatDistance(g.distKm)}</span>
                    <span style="text-align: center; font-size: 0.85rem; color: #bae6fd;">${g.arrow} ${g.compassCode}</span>
                    <span class="worldle-prox-badge">${g.proximity}%</span>
                </div>
            `).join("");
        }
    }
}

window.addEventListener("DOMContentLoaded", () => {
    window.worldleGame = new WorldleGame();
});
